[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$base=Join-Path $root 'target/openspec-evidence/build-extensible-plugin-platform';$runs=@(
 [ordered]@{name='offline';command='powershell -NoProfile -ExecutionPolicy Bypass -File sdk/tests/offline-host-plugin-contract.ps1'},
 [ordered]@{name='abi';command='powershell -NoProfile -ExecutionPolicy Bypass -File sdk/tests/extension-api-abi-contract.ps1'},
 [ordered]@{name='audit';command='python scripts/author_abi_surface_audit.py'} )
Push-Location $root;try{foreach($run in $runs){Invoke-Expression $run.command;if($LASTEXITCODE-ne 0){throw "$($run.name) failed"};$run.result='passed'};$rev=(&git rev-parse HEAD).Trim()}finally{Pop-Location}
$mapping=@{'2.3.1'='offline';'2.3.2'='offline';'2.3.3'='audit';'2.3.4'='abi';'2.3.5'='abi';'2.3.6'='audit';'2.3.7'='offline';'2.3.8'='abi';'2.3.9'='abi';'2.3.10'='abi'}
foreach($id in $mapping.Keys|Sort-Object {[version]$_}){$run=$runs|Where-Object name-eq$mapping[$id];$dir=Join-Path $base $id;New-Item -ItemType Directory -Force $dir|Out-Null;$report=[ordered]@{schema_version=1;task_id=$id;procedure_kind='command';command=$run.command;cwd='.';environment=[ordered]@{validation_authority='local-only';uitest_executed='false';offline='true'};expected='exit code 0';actual='passed';exit_code=0;source_revision=$rev;input_sha256=[ordered]@{}};foreach($path in @('sdk/tests/offline-host-plugin-contract.ps1','sdk/tests/extension-api-abi-contract.ps1','scripts/author_abi_surface_audit.py')){$report.input_sha256[$path]=(Get-FileHash -LiteralPath (Join-Path $root $path) -Algorithm SHA256).Hash.ToLowerInvariant()};$out=Join-Path $dir 'result.json';[IO.File]::WriteAllText($out,(($report|ConvertTo-Json -Depth 5)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false));Write-Output "REPORT $id $((Get-FileHash -LiteralPath $out -Algorithm SHA256).Hash.ToLowerInvariant())"}
